#include "position/ScoreReference.h"
#include <algorithm>
#include <cmath>
namespace temposcore {
bool buildScoreReference(const MidiData&m,ScoreReference&o){o.clear();if(m.ppq<=0)return false;std::vector<double> ticks(static_cast<size_t>(m.totalTicks)+1);double sec=0;int us=500000;size_t ti=0;for(int64_t t=0;t<=m.totalTicks;++t){while(ti<m.tempos.size()&&m.tempos[ti].tick==t){us=m.tempos[ti].microsecondsPerQuarter;++ti;}ticks[t]=sec;sec+=us/1000000.0/m.ppq;}const size_t count=static_cast<size_t>(std::floor(ticks[m.totalTicks]*10))+1;o.frames_.resize(count);size_t cursor=0;for(size_t i=0;i<count;++i){auto&f=o.frames_[i];f.nominalSeconds=i*.1;while(cursor<m.totalTicks&&ticks[cursor]<f.nominalSeconds)++cursor;f.quarterBeatPosition=static_cast<double>(cursor)/m.ppq;for(const auto&n:m.notes){if(n.startTick>static_cast<int64_t>(cursor)||n.endTick<static_cast<int64_t>(cursor))continue;if(n.channel==9){if(std::abs(ticks[n.startTick]-f.nominalSeconds)<.05)f.onset+=n.velocity/127.0f;continue;}f.chroma[n.pitch%12]+=std::sqrt(n.velocity/127.0f);if(std::abs(ticks[n.startTick]-f.nominalSeconds)<.05)f.onset+=n.velocity/127.0f;}}float maxOnset=0;for(const auto&f:o.frames_)maxOnset=std::max(maxOnset,f.onset);for(auto&f:o.frames_){if(maxOnset>0)f.onset/=maxOnset;float norm=0;for(float x:f.chroma)norm+=x*x;norm=std::sqrt(norm);if(norm>0)for(float&x:f.chroma)x/=norm;}return true;}
}
